/**
 * ACUL Entry Point
 *
 * This file is the main entry point for Auth0 ACUL custom screens.
 * When Auth0 loads this compiled JavaScript, it will detect the current
 * screen and render the appropriate custom component.
 */

import { createRoot } from 'react-dom/client';
import { useCurrentScreen } from '@auth0/auth0-acul-react';

// Import custom screens
import LoginIdScreen from './screens/login-id';
import LoginPasswordScreen from './screens/login-password';

// Import global styles
import './styles.css';

/**
 * Main App Component
 * Uses ACUL's useCurrentScreen hook to detect which screen Auth0 is showing
 * and renders the appropriate custom component
 */
function App() {
  const screen = useCurrentScreen() as any;

  // Route to the appropriate screen component based on Auth0's current screen
  const screenId = screen?.screen?.name || screen?.name;

  switch (screenId) {
    case 'login-id':
      return <LoginIdScreen />;
    case 'login-password':
      return <LoginPasswordScreen />;
    default:
      // Fallback for unsupported screens
      return (
        <div className="min-h-screen flex items-center justify-center bg-[#0A0E27]">
          <div className="text-center">
            <h1 className="text-2xl font-display text-white mb-4">
              Screen Not Customized
            </h1>
            <p className="text-[#E6E6FA]/70">
              {screenId ? `Screen: ${screenId}` : 'Unknown screen'}
            </p>
          </div>
        </div>
      );
  }
}

/**
 * Mount the application
 * This runs when Auth0 loads your compiled JavaScript
 */
const root = document.getElementById('root');
if (root) {
  createRoot(root).render(<App />);
} else {
  console.error('❌ Root element not found. ACUL cannot initialize.');
}
