/**
 * ACUL Screen: login-password
 *
 * This screen handles the password input step of the login flow.
 * Uses Auth0 ACUL React SDK v1.2.0 with correct partial imports.
 *
 * Flow: User enters password → Calls login() method → Auth0 authenticates → Redirect to app
 */

import { useState, FormEvent } from 'react';
import {
  useScreen,
  useUser,
  useTransaction,
  useErrors,
  login,
} from '@auth0/auth0-acul-react/login-password';

export default function LoginPasswordScreen() {
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // ACUL hooks
  const screen = useScreen();
  const user = useUser();
  const transaction = useTransaction();
  const { errors } = useErrors();

  // Get the username from the transaction (entered in previous screen)
  const username = user?.username || 'your account';

  /**
   * Handle form submission
   * Call the ACUL login() method to authenticate with password
   */
  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      // Call ACUL's login method with both username and password
      // This authenticates the user and Auth0 handles redirect
      await login({ username: username, password });
    } catch (err) {
      console.error('Login error:', err);
      // Errors are automatically captured by useErrors() hook
    } finally {
      setIsLoading(false);
    }
  };

  /**
   * Go back to the previous screen (login-id)
   */
  const handleBack = () => {
    const txn = transaction as any;
    if (txn?.goBack) {
      txn.goBack();
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#0A0E27] relative overflow-hidden">
      {/* Background Effects */}
      <div className="absolute inset-0 gradient-mesh opacity-50" />
      <div className="absolute inset-0 grid-overlay" />

      {/* Login Card */}
      <div className="relative z-10 w-full max-w-md px-6">
        <div className="glass-card rounded-2xl p-8 scan-lines">
          {/* Header */}
          <div className="text-center mb-8">
            <div className="inline-flex items-center gap-3 px-5 py-3 rounded-full border border-[#00FEFC]/30 bg-[#0A0E27]/80 backdrop-blur-sm mb-6">
              <div className="relative">
                <div className="w-3 h-3 rounded-full bg-[#00FEFC]" />
                <div className="absolute inset-0 w-3 h-3 rounded-full bg-[#00FEFC] animate-ping" />
              </div>
              <span className="font-mono text-sm text-[#E6E6FA] tracking-wider">
                TESSERACT AUTH
              </span>
            </div>

            <h1 className="text-3xl font-display text-white mb-2 tracking-wide">
              ENTER PASSWORD
            </h1>
            <p className="text-[#E6E6FA]/70 text-sm">
              Signing in as <span className="text-[#00FEFC]">{username}</span>
            </p>
          </div>

          {/* Login Form */}
          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label
                htmlFor="password"
                className="block font-mono text-xs text-[#00FEFC] mb-2 tracking-wider"
              >
                PASSWORD
              </label>
              <div className="relative">
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  disabled={isLoading}
                  autoFocus
                  className="w-full px-4 py-3 pr-12 rounded-lg bg-[#0A0E27]/50 border border-[#00FEFC]/20 text-white placeholder-[#E6E6FA]/30 focus:outline-none focus:border-[#00FEFC]/50 transition-colors disabled:opacity-50 font-body"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-[#E6E6FA]/50 hover:text-[#00FEFC] transition-colors"
                  tabIndex={-1}
                >
                  {showPassword ? (
                    <svg
                      className="w-5 h-5"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21"
                      />
                    </svg>
                  ) : (
                    <svg
                      className="w-5 h-5"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"
                      />
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
                      />
                    </svg>
                  )}
                </button>
              </div>
            </div>

            {/* Error Messages */}
            {errors && errors.length > 0 && (
              <div className="space-y-2">
                {errors.map((error, index) => (
                  <div
                    key={index}
                    className="p-3 rounded-lg bg-[#EA00FF]/10 border border-[#EA00FF]/30 animate-fade-in"
                  >
                    <p className="text-[#EA00FF] text-sm font-mono">
                      {error.message || 'Authentication failed'}
                    </p>
                  </div>
                ))}
              </div>
            )}

            {/* Submit Button */}
            <button
              type="submit"
              disabled={isLoading || !password}
              className="w-full relative group disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <div className="absolute inset-0 holographic-border bg-gradient-to-r from-[#00FEFC] to-[#1F51FF] rounded-lg" />
              <div className="relative px-6 py-3 font-display text-sm text-[#0A0E27] tracking-wider flex items-center justify-center gap-2">
                {isLoading ? (
                  <>
                    <svg
                      className="w-5 h-5 animate-spin"
                      fill="none"
                      viewBox="0 0 24 24"
                    >
                      <circle
                        className="opacity-25"
                        cx="12"
                        cy="12"
                        r="10"
                        stroke="currentColor"
                        strokeWidth="4"
                      />
                      <path
                        className="opacity-75"
                        fill="currentColor"
                        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                      />
                    </svg>
                    AUTHENTICATING...
                  </>
                ) : (
                  <>
                    SIGN IN
                    <svg
                      className="w-4 h-4 group-hover:translate-x-1 transition-transform"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                      strokeWidth={2.5}
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        d="M13 7l5 5m0 0l-5 5m5-5H6"
                      />
                    </svg>
                  </>
                )}
              </div>
            </button>

            {/* Back Button */}
            {(transaction as any)?.goBack && (
              <button
                type="button"
                onClick={handleBack}
                disabled={isLoading}
                className="w-full px-4 py-2 text-sm text-[#E6E6FA]/70 hover:text-[#00FEFC] transition-colors font-mono disabled:opacity-50"
              >
                ← Change email
              </button>
            )}
          </form>

          {/* Footer */}
          <div className="mt-6 text-center">
            <a
              href="#forgot-password"
              className="text-sm text-[#EA00FF] hover:text-[#1F51FF] transition-colors"
            >
              Forgot password?
            </a>
          </div>

          {/* Debug Info (Development Only) */}
          {process.env.NODE_ENV === 'development' && (
            <div className="mt-6 p-3 rounded bg-[#0A0E27]/50 border border-[#00FEFC]/10">
              <p className="font-mono text-[10px] text-[#E6E6FA]/50 mb-1">
                ACUL Debug:
              </p>
              <pre className="font-mono text-[9px] text-[#00FEFC]/70 overflow-auto">
                {JSON.stringify(
                  {
                    screen: screen?.name,
                    username: username,
                    errorCount: errors?.length || 0
                  },
                  null,
                  2
                )}
              </pre>
            </div>
          )}
        </div>

        {/* Security Badges */}
        <div className="mt-8 flex items-center justify-center gap-4">
          {['AES-256', 'OAUTH 2.0', 'OIDC'].map((badge) => (
            <span
              key={badge}
              className="px-3 py-1 rounded border border-[#00FEFC]/20 bg-[#00FEFC]/5 font-mono text-[10px] text-[#00FEFC] tracking-widest"
            >
              {badge}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}
